"""Phase 5: Windows 10/11 HVM Automated Guest Deployment.

Author: Nitiraj Kulkarni
"""

import logging
import os
import shutil
from pathlib import Path

from drakvuf_auto.command import command_exists, run_command
from drakvuf_auto.config import DrakvufAutoConfig
from drakvuf_auto.exceptions import GuestProvisioningError
from drakvuf_auto.state import StateManager

logger = logging.getLogger("drakvuf_auto.phase5")

XEN_HVM_TEMPLATE = """# Xen Domain Configuration for DRAKVUF Analysis VM
# Generated by drakvuf-auto-installer

type = "hvm"
name = "{vm_name}"
memory = {memory_mb}
vcpus = {vcpus}
vif = [ 'bridge={bridge}' ]
disk = [
    'format=raw,vdev=xvda,access=w,target={disk_path}'
]
boot = "c"
vnc = 1
vnclisten = "127.0.0.1"
vncdisplay = 0
serial = 'pty'
pae = 1
acpi = 1
apic = 1
viridian = 1
altp2m = 1
nestedhvm = 0
"""


def execute_phase_5(config: DrakvufAutoConfig, state: StateManager, project_root: Path) -> None:
    """Create Windows HVM guest domain and prepare it for agentless VMI."""
    phase_name = "phase_5_guest_deploy"
    if state.is_phase_completed(phase_name):
        logger.info("[bold green]Phase 5 (Guest Deployment) already completed. Skipping.[/bold green]")
        return

    state.start_phase(phase_name)
    logger.info("Starting Phase 5: Windows Guest Deployment (Xen HVM)...")

    # Step 1: Create raw virtual disk for VM
    step_disk = "create_guest_disk"
    if not state.is_step_completed(phase_name, step_disk):
        state.start_step(phase_name, step_disk)
        disk_path = config.guest.disk_path
        disk_path.parent.mkdir(parents=True, exist_ok=True)

        if not disk_path.exists():
            logger.info(f"Allocating {config.guest.disk_size_gb} GB raw disk at {disk_path}...")
            run_command(
                ["qemu-img", "create", "-f", "raw", str(disk_path), f"{config.guest.disk_size_gb}G"],
                stream=True
            )
        state.complete_step(phase_name, step_disk)

    # Step 2: Write Xen HVM domain configuration file
    step_cfg = "generate_xen_domain_config"
    if not state.is_step_completed(phase_name, step_cfg):
        state.start_step(phase_name, step_cfg)
        xen_cfg_path = Path(f"/etc/xen/{config.guest.name}.cfg")
        logger.info(f"Writing Xen domain configuration to {xen_cfg_path}...")

        cfg_content = XEN_HVM_TEMPLATE.format(
            vm_name=config.guest.name,
            memory_mb=config.guest.memory_mb,
            vcpus=config.guest.vcpus,
            bridge=config.network.bridge,
            disk_path=config.guest.disk_path.resolve(),
        )
        xen_cfg_path.parent.mkdir(parents=True, exist_ok=True)
        xen_cfg_path.write_text(cfg_content, encoding="utf-8")
        state.complete_step(phase_name, step_cfg)

    state.complete_phase(phase_name)
    logger.info("[bold green]✓ Phase 5 completed: Windows Xen HVM domain configured.[/bold green]")
